<?php
defined('ABSPATH') || exit;

/** Frontend access screens and navigation. Existing pages are never overwritten. */
final class CAFCC_Portal {
    const VIEWS=array('explorer'=>'Question Explorer','dashboard'=>'My Dashboard','practice'=>'My Practice','mcq'=>'MCQ Practice','trends'=>'Trend Analysis','planner'=>'Study Planner','resources'=>'ICAI Resources','membership'=>'Membership','account'=>'My Account','login'=>'Student Login','register'=>'Create Account','forgot'=>'Forgot Password','pending'=>'Pending Approval','verify'=>'Verify Email','concepts'=>'Quick Concepts');
    public static function assets(){wp_enqueue_style('cafcc-v2',plugins_url('assets/explorer.css',CAFCC_FILE),array(),CAFCC_VERSION);wp_enqueue_script('cafcc-portal',plugins_url('assets/portal.js',CAFCC_FILE),array(),CAFCC_VERSION,true);}
    public static function init(){
        add_shortcode('cafcc_portal',array(__CLASS__,'render'));
        add_action('template_redirect',function(){if(isset($_GET['cafcc_view'])&&is_string($_GET['cafcc_view'])&&isset(self::VIEWS[sanitize_key(wp_unslash($_GET['cafcc_view']))])){nocache_headers();header('Referrer-Policy: no-referrer');self::assets();if(!defined('DONOTCACHEPAGE'))define('DONOTCACHEPAGE',true);status_header(200);echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">';wp_head();echo '</head><body>';echo self::render();wp_footer();echo '</body></html>';exit;}},1);
        add_action('rest_api_init',function(){register_rest_route('cafcc/v4','/admin/pages/prepare',array('methods'=>'POST','permission_callback'=>function($r){return CAFCC_REST::permission($r,true);},'callback'=>array(__CLASS__,'prepare_pages')));});
    }
    public static function url($view){return add_query_arg('cafcc_view',$view,home_url('/'));}
    private static function form($action,$label){$html='<form class="cc-portal-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('cafcc_portal','_wpnonce',true,false).'<input type="hidden" name="action" value="cafcc_portal"><input type="hidden" name="portal_action" value="'.esc_attr($action).'"><input type="hidden" name="return_to" value="'.esc_url(home_url('/')).'">';if('register'===$action)$html.='<label>Your name<input name="student_name" autocomplete="name" maxlength="100" required></label>';if('verify'!==$action)$html.='<label>Email address<input type="email" name="email" autocomplete="email" maxlength="190" required></label>';if(in_array($action,array('login','register'),true))$html.='<label>Password<input type="password" name="password" autocomplete="'.('register'===$action?'new-password':'current-password').'" minlength="'.('register'===$action?'12':'1').'" maxlength="200" required></label>';if('verify'===$action){$uid=isset($_GET['cafcc_uid'])&&is_scalar($_GET['cafcc_uid'])?(string)$_GET['cafcc_uid']:'';$token=isset($_GET['cafcc_token'])&&is_string($_GET['cafcc_token'])?sanitize_text_field(wp_unslash($_GET['cafcc_token'])):'';$html.='<input type="hidden" name="uid" value="'.esc_attr($uid).'"><input type="hidden" name="token" value="'.esc_attr($token).'">';}return $html.'<button type="submit">'.esc_html($label).'</button></form>';}
    public static function render($atts=array()){
        nocache_headers();self::assets();
        $requested=isset($_GET['cafcc_view'])&&is_string($_GET['cafcc_view'])?sanitize_key(wp_unslash($_GET['cafcc_view'])):($atts['view']??'explorer');$view=isset(self::VIEWS[$requested])?$requested:'explorer';$html='<div class="cafcc-v2 cc-portal"><header class="cc-portal-top"><strong>CA Final Command Center</strong><button type="button" class="cc-theme-toggle" aria-pressed="false" aria-label="Switch to dark mode"><span aria-hidden="true">☾</span> <span class="cc-theme-label">Dark mode</span></button></header><nav class="cc-portal-nav" aria-label="Command Center navigation">';
        foreach(array_slice(self::VIEWS,0,9,true) as $key=>$title)$html.='<a href="'.esc_url(self::url($key)).'"'.($key===$view?' aria-current="page"':'').'>'.esc_html($title).'</a>';$help=get_option('cafcc_study_help',array());$html.='<a href="'.esc_url(self::url('concepts')).'">Quick Concepts</a>';if(!empty($help['tutorial_url']))$html.='<a href="'.esc_url($help['tutorial_url']).'" target="_blank" rel="noopener noreferrer">How It Works ↗</a>';$html.='</nav>';
        if(!is_user_logged_in())$html.='<div class="cc-portal-access-links"><a href="'.esc_url(self::url('login')).'">Student Login</a> · <a href="'.esc_url(self::url('register')).'">Create Account</a> · <a href="'.esc_url(self::url('forgot')).'">Forgot Password</a></div>';
        $notices=array('check_email'=>'If eligible, check your email for the verification link. Access remains pending.','pending_approval'=>'Email confirmed. Your account is awaiting administrator approval.','invalid_link'=>'The verification link is invalid or expired. Request a fresh link.','login_failed'=>'Sign-in failed. Check your email/password or use Forgot Password.','request_failed'=>'The request could not be completed. Registration needs a valid email, name and a password of at least 12 characters.','reset_sent'=>'If an account matches, WordPress will email password-reset instructions.','try_later'=>'Please wait before trying again.','signed_in'=>'You are signed in.');$notice=isset($_GET['cafcc_notice'])&&is_string($_GET['cafcc_notice'])?sanitize_key(wp_unslash($_GET['cafcc_notice'])):'';if(isset($notices[$notice]))$html.='<p class="cc-portal-notice" role="status">'.esc_html($notices[$notice]).'</p>';
        if(in_array($view,array('explorer','dashboard','practice'),true)&&!CAFCC_Access::eligible())$view=is_user_logged_in()?'pending':'login';
        if($view==='dashboard')return $html.self::dashboard().'</div>';
        if(in_array($view,array('explorer','practice'),true)){$html.='<p class="cc-portal-intro">'.esc_html(self::VIEWS[$view]).' · Your progress is private and based on saved activity.</p>';return $html.CAFCC_Academic_UI::student($view).'</div>';}
        $html.='<section class="cc-portal-card"><span class="cc-eyebrow">CA FINAL COMMAND CENTER</span><h1>'.esc_html(self::VIEWS[$view]).'</h1>';
        if('login'===$view)$html.=is_user_logged_in()?'<p>You are already signed in. Open My Account or Membership to check access.</p>':self::form('login','Sign in');
        elseif('register'===$view)$html.='<p>Create your WordPress student account. Verify your email, then wait for personal approval. No payment is collected.</p>'.self::form('register','Create account');
        elseif('forgot'===$view)$html.='<p>WordPress will send a secure password-reset link when the address matches an account.</p>'.self::form('forgot','Request password reset');
        elseif('verify'===$view)$html.='<p>Tap below to confirm your email. Opening this page alone does not consume the verification link.</p>'.self::form('verify','Confirm Email');
        elseif(in_array($view,array('pending','account','membership'),true)){
            if(is_user_logged_in()){$r=CAFCC_Access::get(get_current_user_id());if(CAFCC_Repository::admin_allowed()){$r['account_state']='Administrator preview';$r['entitlement_state']='Administrator preview (not a student grant)';}
            $html.='<p>Account: <strong>'.esc_html($r['account_state']).'</strong></p><p>Email: '.((int)$r['email_verified']?'Verified':'Awaiting verification / existing-account review').'</p><p>Access: '.esc_html($r['entitlement_state']).' · Plan: '.esc_html($r['plan_key']?:'Not granted').'</p><p>Expiry: '.esc_html($r['expires_at']?$r['expires_at'].' UTC':'No expiry recorded').'</p>';if(CAFCC_Access::eligible())$html.='<a class="cc-source-link" href="'.esc_url(self::url('explorer')).'">Open Question Explorer</a>';else $html.='<p>Practice access requires a verified email, administrator approval and a current entitlement. Existing test Subscribers are reviewed individually; no account or progress is deleted.</p>';$html.='<p><a href="'.esc_url(wp_logout_url(self::url('login'))).'">Sign out securely</a></p>';}else $html.='<p>Check your verification email, then sign in to view your approval status.</p>';
            if('pending'===$view)$html.='<details><summary>Resend verification email</summary>'.self::form('resend','Resend verification link').'</details>';
            if('membership'===$view)$html.='<p>Access is granted manually in this release. No live payments are enabled. Future plans and verified payment integrations will use the same entitlement checks.</p>';
        }elseif('resources'===$view){$html.=CAFCC_Resources::directory();}
        elseif('concepts'===$view){$v=get_option('cafcc_study_help',array());if(!CAFCC_Access::eligible())$html.='<p>Sign in with current practice access.</p>';else $html.=!empty($v['reviewed'])&&$v['concepts_html']?CAFCC_Practice::html($v['concepts_html']):'<p>No owner-approved editorial Quick Concepts are available yet.</p>';}elseif('trends'===$view){CAFCC_Study::assets();$html.='<div data-study-coverage>Loading approved January 2026 source coverage…</div><p>Multi-year trends and repetition analysis await a reviewed historical corpus.</p>';}elseif(in_array($view,array('planner','mcq'),true))$html.='<p>Coming Soon. This module has no verified data or completed functionality to show yet.</p>';
        return $html.'</section></div>';
    }
    public static function dashboard(){
        CAFCC_Study::assets();
        global $wpdb;$uid=get_current_user_id();$p=CAFCC_DB::table('progress');$n=CAFCC_Practice::table('notebook');$rows=$wpdb->get_results($wpdb->prepare("SELECT status,COUNT(*) AS amount FROM $p WHERE user_id=%d GROUP BY status",$uid),ARRAY_A);$counts=array_fill_keys(CAFCC_Repository::STATUSES,0);foreach($rows as $row)$counts[$row['status']]=(int)$row['amount'];$bookmarks=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $n WHERE user_id=%d AND bookmarked=1",$uid));$notes=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $n WHERE user_id=%d AND note_text<>''",$uid));
        $h='<section class="cc-dashboard" data-cafcc-dashboard><h1>My Dashboard</h1><p>Your saved activity. No exam performance or completion percentage is inferred.</p><div class="cc-summary">';foreach(array('Saved practice records'=>array_sum($counts),'Completed'=>$counts['completed'],'Needs Revision'=>$counts['needs_revision'],'Bookmarks'=>$bookmarks,'Private notes'=>$notes) as $label=>$count)$h.='<div class="cc-stat"><span>'.esc_html($label).'</span><strong>'.esc_html($count).'</strong></div>';$h.='</div><p>Counts include your retained activity on references that may currently await review. My Practice displays only currently eligible questions.</p>';if(!array_sum($counts)&&!$bookmarks&&!$notes)$h.='<p class="cc-empty">You have no saved practice activity yet. Browse the syllabus or open eligible questions to begin.</p>';$h.='<div data-study-dashboard><p>Loading your timed sessions and revision queue…</p></div>';$h.='<p><a class="cc-source-link" href="'.esc_url(self::url('practice')).'">Open My Practice</a> · <a class="cc-source-link" href="'.esc_url(self::url('explorer')).'">Browse the syllabus and questions</a></p></section>';return $h;
    }
    public static function prepare_pages(){if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator access required.',403);$known=get_option('cafcc_v04_pages',array());$created=array();foreach(self::VIEWS as $key=>$title){if($key==='verify')continue;if(!empty($known[$key])&&get_post($known[$key]))continue;$id=wp_insert_post(array('post_type'=>'page','post_title'=>$title,'post_content'=>'[cafcc_portal view="'.$key.'"]','post_status'=>'draft'),true);if(is_wp_error($id))return $id;$known[$key]=$id;$created[$key]=$id;}update_option('cafcc_v04_pages',$known,false);return array('created_drafts'=>$created,'retained_existing_pages'=>true,'published'=>0);}
}
